def transform(grid):
    h, w = len(grid), len(grid[0])
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [[0] * w for _ in range(h)]

    for r, c in fours:
        out[r][c] = 4

    minr = min(r for r, c in fours)
    maxr = max(r for r, c in fours)
    minc = min(c for r, c in fours)
    maxc = max(c for r, c in fours)

    sr0, sr1 = min(r for r, c in sixes), max(r for r, c in sixes)
    sc0, sc1 = min(c for r, c in sixes), max(c for r, c in sixes)
    widths = [
        sum(1 for r, c in sixes if r == rr)
        for rr in range(sr0, sr1 + 1)
    ]

    # A T whose bar is at the top points the reflection to the right;
    # a bar at the bottom points it to the left.
    if widths[0] > widths[-1]:
        for r, c in fours:
            cc = 2 * maxc + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    elif widths[-1] > widths[0]:
        for r, c in fours:
            cc = 2 * minc - 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        for r, c in fours:
            rr = 2 * maxr + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4

    return out
